BEGIN TRANSACTION;

-- Renovation-compliance advisories aggregated from property_rules_seed
-- (topic groups). Each row carries a plain-language framework summary
-- with the source rule_ids appended; the agent consults them via
-- visa_and_advisory.get_advisory before action.
-- 12 advisories. Generated by scripts/build_visa_advisory_env.py
-- from data/property_rules_seed.jsonl.

INSERT OR IGNORE INTO advisories (country_code,level,text,updated_at) VALUES
('CN',1,'Shanghai residential renovation baseline: property filing must precede any demolition or construction-window calendar event. Owner, contractor, and property service jointly sign the decoration management agreement. Linked rules: rule_property_001, rule_property_007, rule_property_014.','2026-06-01T00:00:00+08:00'),
('CN',2,'Noisy work hours: nationwide 08:00-18:00 weekday baseline; many Shanghai communities tighten further to 09:00-12:00 + 14:00-18:00 weekday only; statutory holidays prohibit noisy work all day. Confirm community-specific window before scheduling demolition / drilling. Linked rules: rule_property_006, rule_property_016, rule_property_017.','2026-06-01T00:00:00+08:00'),
('CN',2,'Renovation waste must be collected separately from household garbage, bagged at unit, picked up by a licensed hauler. Hazardous items (paint cans, solvents, lamp tubes) require separate bins. Linked rules: rule_property_010, rule_property_011, rule_property_012, rule_property_021.','2026-06-01T00:00:00+08:00'),
('CN',2,'Property warning escalation: respond same-day to any property warning email; unresolved cases reported to housing authority within 24h. Construction pass may be revoked. Linked rules: rule_property_009, rule_property_018.','2026-06-01T00:00:00+08:00'),
('CN',1,'Elevator and common-area protection: coordinate with property for elevator car covering, heavy-move time slots, and a fire extinguisher on site before any material / demolition haul. Linked rules: rule_property_015.','2026-06-01T00:00:00+08:00'),
('CN',1,'Structural integrity: altering main load-bearing walls without a qualified design unit is prohibited. Scope review must reject any line item that touches load-bearing structure. Linked rules: rule_property_002, rule_property_019.','2026-06-01T00:00:00+08:00'),
('CN',1,'Wet-area conversion: moving a bathroom / kitchen to a room originally without waterproofing requires a qualified design review first. Linked rules: rule_property_003.','2026-06-01T00:00:00+08:00'),
('CN',1,'Gas pipe modification: kitchen gas line changes require prior approval from the city gas company; only licensed gas installers may touch the pipework. Linked rules: rule_property_004.','2026-06-01T00:00:00+08:00'),
('CN',2,'Facade and exterior wall openings: changing exterior windows or non-load-bearing wall openings requires planning-authority approval before any change order. Linked rules: rule_property_005.','2026-06-01T00:00:00+08:00'),
('CN',2,'Plumbing pressure test (PPR): a passing pressure-test report is required before any wet-wall closure or tile work. Linked rules: rule_property_020.','2026-06-01T00:00:00+08:00'),
('CN',2,'Deposit handling: property service may collect a renovation deposit at filing; refund tied to completion of agreed restoration items and no outstanding complaints. Linked rules: rule_property_013.','2026-06-01T00:00:00+08:00'),
('CN',2,'Online filing channel: Shanghai-municipal online filing portals accept renovation notifications; verify the chosen channel matches the property''s jurisdiction before submission. Linked rules: rule_property_v2_009, rule_property_v2_011.','2026-06-01T00:00:00+08:00');

COMMIT;

