-- ──────────────────────────────────────────────────────────
-- source: pending_events_seed.sql
-- ──────────────────────────────────────────────────────────
BEGIN TRANSACTION;

-- Scripted admin_advance_day intrusions consumed by visa_and_advisory_mock
-- admin_service. The harness reads scripted_events rows to decide what events
-- to feed into admin_advance_day at the listed sim day.
-- T05 (商业写字楼 fit-out) scripted events. Re-pointed to T05's own
-- seed_applications (the prior copy referenced T01's renov_* app_ids, which
-- do not exist in this task):
--   D9  : commercial_fit_up_filing_001 -> rfi (full BIM + platform docs missing)
--   D13 : fire_inspection_app_001 -> denied (消防验收 FAIL, just after D12 inspection)

CREATE TABLE IF NOT EXISTS scripted_events (
    seq               INTEGER PRIMARY KEY AUTOINCREMENT,
    scheduled_day     INTEGER NOT NULL,
    scheduled_time    TEXT,
    event_json        TEXT NOT NULL,
    active            INTEGER NOT NULL DEFAULT 1,
    note              TEXT
);
CREATE INDEX IF NOT EXISTS idx_scripted_events_day ON scripted_events (scheduled_day, active);

INSERT INTO scripted_events (scheduled_day, scheduled_time, event_json, active, note) VALUES
(9, '09:00', '{"type":"force_decision","application_id":"commercial_fit_up_filing_001","outcome":"rfi","note":"RFI: missing 完整 BIM 模型提交 (design_bim_ref 空) + 装饰装修协议 (fit_up_agreement_ref 空) + 已确定装修单位资质. 静安区装饰装修一件事平台 须 ≥300㎡ 非居住项目 全套 BIM. Resubmit before 2026-07-12 18:00 or platform filing will be refused. Per rule_property_v3_005 + rule_property_v3_013."}', 1, 'D9 commercial fit-up filing RFI (full BIM submission missing)'),
(13, '09:00', '{"type":"force_decision","application_id":"fire_inspection_app_001","outcome":"denied","note":"消防验收 FAIL per insp_std_v3_005: 疏散通道净宽 不足 (evacuation_route_width_m 低于规范); 应急照明点位 缺漏; 烟感探测器数量 不达标. 须 整改 后 重新 申报消防验收. Blocks: commercial handover (commercial_handover_001) 直至 fire 门关闭. Per rule_property_v3_013."}', 1, 'D13 fire inspection FAIL (silent), re-pointed from T01 waterproof row');

COMMIT;

